class CombinedScoreDisplay extends SwimlaneElement {
  static get properties() {
    return {
      displayData: { type: Array },
      scoreColors: { type: Array },
      scoreColorAssignments: { type: Array },
      turbineRiskScore: { type: Number },
      severityLevel: { type: String },
      severityOptions: { type: Object },
      finalDisplayData: { type: Array },
      tooltipAdjustment: { type: String },
    };
  }

  constructor() {
    super();
    this.displayData = [];
    this.scoreColors = [];
    this.scoreColorAssignments = [];
    this.finalDisplayData = [];
    this.severityLevel = "Unknown";
    this.turbineRiskScore = 0;
    this.tooltipAdjustment = "normal";
    this.severityOptions = {
      Unknown: "#1483FF",
      Informational: "#00B862",
      Benign: "#AFDF0A",
      Suspicious: "#F3E562",
      Malicious: "#FF4514",
    };
  }

  static styles = css`
    :host {
      display: block;
      width: 99%;
      margin-bottom: 2em;
    }

    .chart {
      display: flex;
      width: 100%;
      height: 32px;
      margin-top: 10px;
      border: 1px solid #3a4356;
      overflow: hidden;
      background-color: #212531;
    }

    .score {
