      background-color: #212630;
    }

    .key-color {
      width: 20px;
      height: 20px;
      border-radius: 2px;
      display: inline-block;
      margin-right: 5px;
    }

    .popover-container {
      position: relative;
    }

    .tooltip {
      background: #afb7c8;
      color: #2b2e34;
      font-family: "Source Sans Pro", "Open Sans", Arial, sans-serif;
      font-size: 12px;
      opacity: 0;
      padding: 4px 8px;
      pointer-events: none;
      position: absolute;
      transition: opacity 0.2s ease;
      white-space: nowrap;
      z-index: 1000;
      border: none;
    }

    .tooltip.visible {
      opacity: 1;
    }

    .tooltip.normal::after {
      content: "";
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      width: 0;
      height: 0;
      border-left: 6px solid transparent;
      border-right: 6px solid transparent;
      border-top: 6px solid #afb7c8;
    }

    .tooltip.adjust-left::after {
      content: "";
      position: absolute;
      bottom: -5px;
      left: 0;
      width: 0;
      height: 0;
      border-style: solid;
      border-width: 5px 5px 0 0;
      border-color: #afb7c8 transparent transparent transparent;
    }

    .tooltip.adjust-right::after {
      content: "";
      position: absolute;
      bottom: -5px;
      right: 0;
      width: 0;
      height: 0;
      border-style: solid;
      border-width: 5px 0 0 5px;
      border-color: #afb7c8 transparent transparent transparent;
    }

    .indicator {
      width: 10px;
      height: 10px;
      min-width: 10px;
      border: var(--indicatorColor);
      border-radius: 50%;
      background: var(--indicatorColor);
      margin-right: 10px;
      align-self: center;
    }
    .top-row {
      display: flex;
      padding: 2px;
    }
    .indicator-block {
      display: flex;
      background-color: #303847;
      border-radius: 2px;
      padding-left: 10px;
      padding-right: 10px;
      padding-bottom: 3px;
    }
    .label-text {
      color: #cdd2de;
      font-family: "Source Sans Pro", "Open Sans", Arial, sans-serif;
      font-size: 16px;
    }
    .score-summary {
      color: #ffffff;
      background-color: transparent;
      margin-left: 1em;
    }
    .popover-toggle {
      display: inline-block;
      background: none;
      border: none;
      color: inherit;
      font: inherit;
      line-height: normal;
      margin: 0;
      padding: 0;
      overflow: visible;
      text-transform: none;
      cursor: pointer;
    }
  `;

  render() {
    const totalScore = this.getTotalScore();

    return html`
      <div class="top-row">
        <div class="indicator-block">
          <div
            class="indicator"
            style="--indicatorColor:${this.severityOptions[this.severityLevel]}"
          ></div>
          <div class="label-text">${this.severityLevel}</div>
        </div>
        <div class="score-summary">${this.turbineRiskScore} / ${totalScore}</div>
      </div>
      <div class="tooltip"></div>
      <div class="chart">
        ${this.finalDisplayData.map((item, index) => {
          const scoreWidth = (item["Normalized Score"] / totalScore) * 100;

          if (scoreWidth > 0) {
            return html`
              <div
                class="score"
                style="width: ${scoreWidth}%; 
                              background-color: ${item.color};"
                @mouseover=${(e) => this.showTooltip(e, item)}
                @mouseout=${this.hideTooltip}
              ></div>
            `;
          } else {
            return html``;
          }
        })}
      </div>
      <slit-section-component
        sectionTitle="Risk Elements"
        sectionCollapsed="false"
        sectionCollapsible="true"
      >
        <table class="key-table">
          <thead>
            <tr>
              <th></th>
              <th>Turbine Risk Element Name</th>
              <th>Raw Score</th>
              <th>Weight</th>
              <th>Normalized Score</th>
              <th>Description</th>
            </tr>
          </thead>
          <tbody>
            ${this.finalDisplayData.map((item, index) => {
              return html`
                <tr
                  class="key-row"
                  @mouseover=${() => this.highlightScore(index)}
                  @mouseout=${() => this.removeHighlight(index)}
                >
                  <td>
                    <div
                      class="key-color"
                      style="background-color: ${item.color};"
                    ></div>
                  </td>
                  <td class="popover-container">
                    <button
                      class="popover-toggle"
                      id="${'popover-toggle' + index}"
                      tooltiptarget="${'popover-target' + index}"
                      @mouseover=${(e) => this.showDescriptionTooltip(e)}
                      @mouseout=${(e) => this.hideDescriptionTooltip(e)}
                    >
                      ${item["Turbine Risk Score Element Name"]}
                    </button>
                    <div
                      class="${"popover-" + index} tooltip popover-tooltip"
                      id="${"popover-target" + index}"
                    >
                      ${item["Description"]}
                    </div>
                  </td>
                  <td>${item["Raw Score"]}</td>
                  <td>${item["Weight"]}</td>
                  <td>${item["Normalized Score"]}</td>
                  <td>${item["Description"]}</td>
                </tr>
              `;
            })}
          </tbody>
        </table>
      </slit-section-component>
    `;
  }

  updated(changedProperties) {
    super.updated(changedProperties);
    if (
      changedProperties.has("displayData") ||
      changedProperties.has("scoreColorAssignments")
    ) {
      this._prepareFinalDisplayData();
    }
  }

  _prepareFinalDisplayData() {
    this.finalDisplayData = [];
    let addedItems = new Set();

    this.displayData.forEach((item) => {
      const colorAssignment = this.scoreColorAssignments.find(
        (assignment) =>
          assignment.name === item["Turbine Risk Score Element Name"]
      );

      if (colorAssignment) {
        this.finalDisplayData.push({ ...item, color: colorAssignment.color });
        addedItems.add(item);
      }
    });

    this.displayData.forEach((item, index) => {
      if (!addedItems.has(item)) {
        const color = this.scoreColors[index % this.scoreColors.length];
        this.finalDisplayData.push({ ...item, color });
      }
    });
  }

  getTotalScore() {
    return 1000; // Total "Normalized Score" is out of 1000
  }

  showDescriptionTooltip(event) {
    const tooltipContent = this.shadowRoot.querySelector("#" + event.target.getAttribute("tooltiptarget"));

    const tooltip = this.shadowRoot.querySelector(".tooltip");
    const table = this.shadowRoot.querySelector(".key-table");

    tooltip.innerHTML = tooltipContent.innerHTML;

    const targetRect = event.target.getBoundingClientRect();
    const tableRect = table.getBoundingClientRect();

    // where is the 130 coming from? probably not exactly 130 because margin included.

    tooltip.style.top = `${targetRect.top - tableRect.top + 100}px`;
    tooltip.style.left = `${targetRect.left - tableRect.left - (targetRect.width / 2)}px`;

    this.tooltipAdjustment = "normal";

    tooltip.classList.add("visible", this.tooltipAdjustment);
  }

  hideDescriptionTooltip(event) {
     const tooltip = this.shadowRoot.querySelector(".tooltip");

    tooltip.classList.remove("visible", this.tooltipAdjustment);
  }


  showTooltip(event, item) {
    const tooltip = this.shadowRoot.querySelector(".tooltip");

    let innerHTML = item[TOOLTIP_TITLE_PROPERTY];
    TOOLTIP_DISPLAY_PROPERTIES.forEach((key) => {
      innerHTML += `<br>${key} : ${item[key]}`;
    });
    tooltip.innerHTML = innerHTML;

    const computedStyles = window.getComputedStyle(tooltip);
    const lineHeight = parseFloat(
      computedStyles.getPropertyValue("line-height")
    );
    const totalHeight = parseFloat(computedStyles.getPropertyValue("height"));
    const lineCount = Math.ceil(totalHeight / lineHeight);
    const topOffset = 27 - lineCount * 17;

    const targetRect = event.target.getBoundingClientRect();
    const chart = this.shadowRoot.querySelector(".chart");
    const chartRect = chart.getBoundingClientRect();
    const tooltipRect = tooltip.getBoundingClientRect();

    let targetRectJson = {
      left: targetRect.left,
      right: targetRect.right,
      width: targetRect.width,
    };

    let chartRectJson = {
      left: chartRect.left,
      right: chartRect.right,
      width: chartRect.width,
    };

    let tooltipRectJson = {
      left: tooltipRect.left,
      right: tooltipRect.right,
      width: tooltipRect.width,
    };

    let leftOffset =
      targetRect.left -
      chartRect.left +
      targetRect.width / 2 -
      tooltipRect.width / 2;

    if (leftOffset < 0) {
      this.tooltipAdjustment = "adjust-left";

      leftOffset = targetRect.left - chartRect.left;
    } else if (leftOffset + tooltipRect.width > chartRect.width) {
      this.tooltipAdjustment = "adjust-right";

      leftOffset = targetRect.right - tooltipRect.width - chartRect.left;
    } else {
      this.tooltipAdjustment = "normal";
    }

    tooltip.style.top = `${topOffset}px`;

    tooltip.style.left = `${leftOffset}px`;

    tooltip.classList.add("visible", this.tooltipAdjustment);
  }

  hideTooltip() {
    const tooltip = this.shadowRoot.querySelector(".tooltip");

    tooltip.classList.remove("visible", this.tooltipAdjustment);
  }

  highlightScore(index) {
    const scoreDiv = this.shadowRoot.querySelector(
      `.score[data-index="${index}"]`
    );

    if (scoreDiv) {
      scoreDiv.classList.add("highlight");
    }
  }

  removeHighlight(index) {
    const scoreDiv = this.shadowRoot.querySelector(
      `.score[data-index="${index}"]`
    );

    if (scoreDiv) {
      scoreDiv.classList.remove("highlight");
    }
  }
}

